"""Demo: the Euler characteristic on virtual graded spaces (Laurent polynomials).

Computes chi(sum a_d T^d) = sum (-1)^d a_d and verifies the negative-dimensional
formula chi(pureSpace(-n,k)) = (-1)^n k, including chi = -k in dimension -1.
"""
from __future__ import annotations
from typing import Dict


def chi(coeffs: Dict[int, int]) -> int:
    """Euler characteristic: sum of (-1)^d * a_d over dimensions d."""
    return sum((1 if d % 2 == 0 else -1) * c for d, c in coeffs.items())


def pure_space(dim: int, k: int) -> Dict[int, int]:
    """k components concentrated in dimension `dim`."""
    return {dim: k} if k else {}


if __name__ == "__main__":
    for k in range(1, 6):
        assert chi(pure_space(-1, k)) == -k
        print(f"dim -1, {k} comps -> chi = {chi(pure_space(-1, k))}")
    for n in range(6):
        assert chi(pure_space(-n, 1)) == (-1) ** n
        print(f"dim -{n} -> chi = {chi(pure_space(-n, 1))}")

"""Demo: chi is a surjective ring homomorphism (additivity, Kunneth product).

Verifies chi(X+Y)=chi(X)+chi(Y), chi(X*Y)=chi(X)*chi(Y), chi(1)=1, and that
every integer is realized as chi(C(m)).
"""
from __future__ import annotations
from typing import Dict

Poly = Dict[int, int]


def chi(x: Poly) -> int:
    return sum((1 if d % 2 == 0 else -1) * c for d, c in x.items())


def add(x: Poly, y: Poly) -> Poly:
    out = dict(x)
    for d, c in y.items():
        out[d] = out.get(d, 0) + c
    return {d: c for d, c in out.items() if c}


def mul(x: Poly, y: Poly) -> Poly:
    out: Poly = {}
    for d1, c1 in x.items():
        for d2, c2 in y.items():
            out[d1 + d2] = out.get(d1 + d2, 0) + c1 * c2
    return {d: c for d, c in out.items() if c}


if __name__ == "__main__":
    x = {2: 3, -1: 4}
    y = {0: 5, 3: -2}
    assert chi(add(x, y)) == chi(x) + chi(y)
    assert chi(mul(x, y)) == chi(x) * chi(y)
    assert chi({0: 1}) == 1
    for m in (-3, 0, 7):
        assert chi({0: m}) == m
    print("Ring-homomorphism laws verified; chi is surjective onto Z.")

"""Demo: Spanier-Whitehead duality D(T^d)=T^{-d}, an involution preserving chi.

Verifies D(D(X))=X, chi(D(X))=chi(X), and that D swaps suspension/desuspension.
Also exhibits a chi-collision separated by the top-degree invariant.
"""
from __future__ import annotations
from typing import Dict

Poly = Dict[int, int]


def chi(x: Poly) -> int:
    return sum((1 if d % 2 == 0 else -1) * c for d, c in x.items())


def dual(x: Poly) -> Poly:
    return {-d: c for d, c in x.items() if c}


def susp(x: Poly) -> Poly:
    return {d + 1: c for d, c in x.items() if c}


def desusp(x: Poly) -> Poly:
    return {d - 1: c for d, c in x.items() if c}


def top_dim(x: Poly) -> int:
    return max(d for d, c in x.items() if c)


if __name__ == "__main__":
    x = {-1: 4, 3: 2, 0: -5}
    assert dual(dual(x)) == x
    assert chi(dual(x)) == chi(x)
    assert dual(susp(x)) == desusp(dual(x))
    a, b = {0: 1}, {2: 1}
    assert chi(a) == chi(b) and a != b and top_dim(a) != top_dim(b)
    print("Duality is an involution preserving chi; topDim separates T^0 and T^2.")

