function EulerCharacteristic(coeffs):
    total <- 0
    for (d, a) in coeffs:
        if d is even: total <- total + a
        else:         total <- total - a
    return total

function Suspend(coeffs, m):
    result <- empty map
    for (d, a) in coeffs:
        if a != 0: result[d + m] <- a
    return result

function Dual(coeffs):
    result <- empty map
    for (d, a) in coeffs:
        if a != 0: result[-d] <- a
    return result

