"""Mirror plot: Spanier-Whitehead duality reflects dimensions across zero.

Displays a virtual graded space and its dual as stem plots, showing the
reflection T^d -> T^{-d} while chi is preserved.
"""
import matplotlib.pyplot as plt


def dual(coeffs):
    return {-d: a for d, a in coeffs.items()}


def chi(coeffs):
    return sum(a if d % 2 == 0 else -a for d, a in coeffs.items())


def main() -> None:
    x = {-1: 4, 0: -5, 3: 2}
    dx = dual(x)
    fig, axes = plt.subplots(1, 2, figsize=(11, 4), sharey=True)
    for ax, (p, title) in zip(axes, [(x, "X"), (dx, "D X")]):
        ds = sorted(p)
        ax.stem(ds, [p[d] for d in ds])
        ax.axvline(0, color="grey", linewidth=0.8, linestyle="--")
        ax.set_title(f"{title}   (chi = {chi(p)})")
        ax.set_xlabel("dimension d")
    axes[0].set_ylabel("coefficient")
    fig.suptitle("Duality reflects dimensions across zero and preserves chi")
    plt.tight_layout()
    plt.savefig("duality_mirror.png", dpi=150)
    print("wrote duality_mirror.png")


if __name__ == "__main__":
    main()

